# Build the Flutter Windows client. Run from anywhere:
#   powershell -ExecutionPolicy Bypass -File flutter_app\scripts\build_windows.ps1
# The platform runner (windows\) is generated by the local Flutter SDK to match
# its own version; lib\ and pubspec.yaml are never overwritten.
$ErrorActionPreference = 'Stop'
$app = (Resolve-Path (Join-Path $PSScriptRoot '..')).Path
Set-Location $app

$flutter = Get-Command flutter -ErrorAction SilentlyContinue
if (-not $flutter) { throw 'flutter not found in PATH. Install Flutter SDK (Windows desktop support) first.' }

# Back up the two files flutter create might touch; restore afterwards.
Copy-Item 'lib\main.dart' 'lib\main.dart.bak' -Force
Copy-Item 'pubspec.yaml' 'pubspec.yaml.bak' -Force
try {
    & flutter create --platforms=windows --project-name super_brain --org com.superbrain . 2>&1 | Out-Host
    $mainNow = (Get-Content 'lib\main.dart' -Raw)
    $mainBak = (Get-Content 'lib\main.dart.bak' -Raw)
    if ($mainNow -ne $mainBak) { Copy-Item 'lib\main.dart.bak' 'lib\main.dart' -Force }
    Copy-Item 'pubspec.yaml.bak' 'pubspec.yaml' -Force
} finally {
    Remove-Item 'lib\main.dart.bak' -ErrorAction SilentlyContinue
    Remove-Item 'pubspec.yaml.bak' -ErrorAction SilentlyContinue
}

& flutter pub get 2>&1 | Out-Host
if ($LASTEXITCODE -ne 0) { throw 'flutter pub get failed' }
# --no-tree-shake-icons: 图标被 tree-shake 后，只在 const Map 里动态引用的字形
# （如左栏「记忆洞察」「Agent 上下文」）会缺失，界面表现为菜单没图标。
& flutter build windows --release --no-tree-shake-icons 2>&1 | Out-Host
if ($LASTEXITCODE -ne 0) { throw 'flutter build windows failed' }

$exe = Join-Path $app 'build\windows\x64\runner\Release\super_brain.exe'
Write-Output "BUILD OK: $exe"
